c='p0';B='AI 1'
def box(x,y,w,h,t,f='#BBDEFB',s='#1565C0',fs=20):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="8" fill="{f}" stroke="{s}" stroke-width="3"/><text x="{x+w/2}" y="{y+h/2+7}" text-anchor="middle" font-size="{fs}" font-weight="800" fill="#0B2545" font-family="sans-serif">{t}</text>'
def ar(x1,y1,x2,y2,col='#D84315'): return f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="{col}" stroke-width="4" marker-end="url(#a)"/>'
DEF='<defs><marker id="a" markerWidth="8" markerHeight="8" refX="6" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="#D84315"/></marker></defs>'
def svg(h,b): return f'<svg viewBox="0 0 520 {h}" style="width:100%">{DEF}{b}</svg>'
S=[]
S.append(TITLE('TIN HỌC · TRÍ TUỆ NHÂN TẠO 1','AI: KHÁI NIỆM, ỨNG DỤNG<br>VÀ ĐẠO ĐỨC','Trí tuệ nhân tạo là gì, lịch sử, ứng dụng, AI tạo sinh, hạn chế, đạo đức, pháp lí, sử dụng AI có trách nhiệm.',['AI','ứng dụng','AI tạo sinh','thiên lệch','đạo đức']))
S.append(goals(c,B,['Nêu <b>khái niệm</b> và đặc trưng của trí tuệ nhân tạo.','Kể <b>ứng dụng</b> của AI trong đời sống, học tập, sản xuất.','Giải thích <b>AI tạo sinh</b> và hạn chế (ảo giác, thiên lệch).','Nhận biết <b>vấn đề đạo đức, pháp lí</b> khi dùng AI.','Sử dụng AI <b>có trách nhiệm</b>.'],['Khái niệm AI','Ứng dụng AI','AI tạo sinh','Hạn chế, rủi ro','Đạo đức, trách nhiệm']))
S.append(S2(c,B+' · 1','Trí tuệ nhân tạo là gì?',card('Khái niệm',ul(['<b>Trí tuệ nhân tạo (AI)</b>: khả năng của máy tính thực hiện các việc cần <b>trí thông minh con người</b>: nhận thức, học, suy luận, ra quyết định.','Không phải <b>suy nghĩ như người</b> mà là <b>xử lí dữ liệu theo mô hình</b>.'],6)),KEY('Ba thành phần: <b>dữ liệu</b>, <b>thuật toán</b> (mô hình), <b>sức mạnh tính toán</b>.')))
S.append(TB(c,B+' · 1','Lịch sử tóm tắt',['Thời kì','Sự kiện'],[['<b>1950</b>','Alan Turing đề xuất “phép thử Turing”'],['<b>1956</b>','thuật ngữ “Artificial Intelligence” ra đời (Dartmouth)'],['<b>1997</b>','máy Deep Blue thắng nhà vô địch cờ vua Kasparov'],['<b>2016</b>','AlphaGo thắng kì thủ cờ vây Lee Sedol'],['<b>2022 →</b>','AI tạo sinh (ChatGPT…) phổ biến toàn cầu']],note=KEY('Bước ngoặt gần đây nhờ <b>dữ liệu lớn</b>, <b>học sâu</b> và phần cứng (GPU).')))
S.append(S2(c,B+' · 1','AI hẹp và AI tổng quát',T(tr('Loại','Đặc điểm','Hiện nay',h=True)+tr('<b>AI hẹp</b> (Narrow AI)','giỏi <b>một</b> nhiệm vụ','<b>đang có</b>: nhận diện ảnh, dịch, cờ vây')+tr('<b>AI tổng quát</b> (AGI)','làm được <b>mọi việc trí tuệ</b> như người','chưa có')),KEY('Mọi AI đang dùng đều là <b>AI hẹp</b>; một hệ thống giỏi cờ vây <b>không</b> tự biết lái xe.')+WARN('Phim ảnh thường thổi phồng; AI chưa có <b>ý thức, cảm xúc</b> thật sự.')))
S.append(S2(c,B+' · 2','Ứng dụng của AI',card('Lĩnh vực',ul(['<b>Y tế</b>: đọc ảnh X-quang, hỗ trợ chẩn đoán.','<b>Giáo dục</b>: gia sư ảo, chấm bài, cá nhân hoá học tập.','<b>Giao thông</b>: xe tự lái, dẫn đường.','<b>Nông nghiệp</b>: nhận biết sâu bệnh qua ảnh.','<b>Ngân hàng</b>: phát hiện giao dịch gian lận.'],6)),KEY('Đời sống hàng ngày: <b>trợ lí ảo</b>, <b>dịch tự động</b>, <b>gợi ý</b> phim, nhạc, <b>mở khoá bằng khuôn mặt</b>.')))
S.append(TB(c,B+' · 2','Các nhóm bài toán AI',['Nhóm','Việc làm được','Ví dụ'],[['<b>Thị giác máy tính</b>','nhận diện ảnh, video','mở khoá khuôn mặt'],['<b>Xử lí ngôn ngữ tự nhiên</b>','hiểu, dịch, sinh văn bản','dịch máy, chatbot'],['<b>Nhận dạng giọng nói</b>','chuyển tiếng nói ↔ văn bản','trợ lí ảo'],['<b>Hệ gợi ý</b>','đề xuất theo sở thích','gợi ý video, sản phẩm'],['<b>Robot, điều khiển</b>','hành động trong môi trường','robot hút bụi, xe tự lái']],note=KEY('Phần lớn dựa trên <b>học máy</b>: máy học từ dữ liệu thay vì được lập trình từng quy tắc.')))
S.append(S2(c,B+' · 2','Chương trình truyền thống và học máy',RES(svg(260,'<text x="260" y="25" text-anchor="middle" font-size="20" font-weight="800" font-family="sans-serif" fill="#1565C0">LẬP TRÌNH TRUYỀN THỐNG</text>'+box(10,45,100,44,'Dữ liệu')+box(130,45,110,44,'Quy tắc','#FFF9C4','#F9A825')+box(380,45,130,44,'Kết quả','#C8E6C9','#2E7D32')+ar(110,67,130,67)+ar(240,67,380,67)+'<text x="260" y="150" text-anchor="middle" font-size="20" font-weight="800" font-family="sans-serif" fill="#D84315">HỌC MÁY</text>'+box(10,170,100,44,'Dữ liệu')+box(130,170,110,44,'Kết quả','#C8E6C9','#2E7D32')+box(380,170,130,44,'Mô hình','#FFF9C4','#F9A825',20)+ar(110,192,130,192)+ar(240,192,380,192)),'So sánh'),card('Khác biệt',ul(['Truyền thống: <b>con người viết quy tắc</b>.','Học máy: máy <b>tự rút ra quy tắc</b> từ dữ liệu có kết quả.'],6))))
S.append(S2(c,B+' · 3','AI tạo sinh (Generative AI)',card('Khái niệm',ul(['AI <b>tạo ra nội dung mới</b>: văn bản, hình ảnh, âm thanh, mã chương trình.','Học <b>quy luật thống kê</b> từ lượng dữ liệu rất lớn, rồi sinh nội dung theo yêu cầu (<b>prompt</b>).','Ví dụ: chatbot, tạo ảnh từ mô tả.'],6)),KEY('Mô hình ngôn ngữ lớn (<b>LLM</b>) sinh văn bản bằng cách <b>dự đoán từ tiếp theo</b> có khả năng cao nhất.')))
S.append(S2(c,B+' · 3','Viết yêu cầu (prompt) hiệu quả',card('Cấu trúc gợi ý',ul(['<b>Vai trò</b>: “Bạn là giáo viên Tin học”.','<b>Nhiệm vụ</b> rõ ràng.','<b>Bối cảnh</b>, đối tượng.','<b>Định dạng</b> đầu ra, độ dài.'],6)),KEY('Ví dụ: “Là giáo viên Tin 10, giải thích <b>địa chỉ IP</b> cho học sinh lớp 10 trong <b>5 dòng</b>, kèm <b>1 ví dụ</b>.”')+OK('Yêu cầu càng <b>cụ thể</b> càng cho kết quả tốt; có thể <b>hỏi lại, chỉnh sửa</b> nhiều lượt.')))
S.append(S2(c,B+' · 3','Hạn chế của AI tạo sinh',card('Các hạn chế',ul(['<b>Ảo giác</b> (hallucination): bịa thông tin nghe rất hợp lí.','<b>Thiên lệch</b> từ dữ liệu huấn luyện.','Kiến thức dừng ở <b>thời điểm huấn luyện</b>.','Không <b>hiểu</b> thật sự, có thể sai logic, toán.'],6)),WARN('Luôn <b>kiểm chứng</b> thông tin quan trọng bằng nguồn tin cậy; không nộp bài do AI viết như của mình.')))
S.append(S2(c,B+' · 3','Ví dụ ảo giác',RES(OUT('Hỏi: Ai là tác giả cuốn “Giáo trình Tin học Vũ Trụ 2099”?\nAI: “Cuốn sách do GS. Nguyễn Văn A biên soạn năm 2021…” \n→ sách KHÔNG tồn tại, AI vẫn trả lời tự tin.',20),'Ảo giác'),KEY('AI sinh câu <b>nghe hợp lí</b> chứ không <b>tra cứu sự thật</b>. Phải <b>đối chiếu nguồn</b>.')+OK('Cách giảm: yêu cầu nêu nguồn, hỏi lại, kiểm tra nhiều nguồn.')))
S.append(S2(c,B+' · 4','Thiên lệch và công bằng',card('Thiên lệch (bias)',ul(['Dữ liệu huấn luyện <b>phản ánh định kiến</b> xã hội.','Ví dụ: hệ thống tuyển dụng ưu tiên một giới; nhận diện khuôn mặt kém chính xác với một số nhóm.'],6)),KEY('“<b>Rác vào – rác ra</b>” (garbage in, garbage out): dữ liệu lệch → mô hình lệch.')+OK('Giải pháp: dữ liệu <b>đa dạng, cân bằng</b>; kiểm tra, đánh giá theo từng nhóm.')))
S.append(TB(c,B+' · 4','Các vấn đề đạo đức khi dùng AI',['Vấn đề','Biểu hiện','Cách ứng xử'],[['<b>Riêng tư</b>','thu thập, lộ dữ liệu cá nhân','không đưa thông tin nhạy cảm vào AI'],['<b>Bản quyền</b>','huấn luyện, sinh nội dung giống tác phẩm có sẵn','nêu nguồn, tôn trọng quyền tác giả'],['<b>Trung thực học thuật</b>','nhờ AI làm bài rồi nộp','dùng để <b>học</b>, ghi rõ khi dùng'],['<b>Tin giả, deepfake</b>','ảnh, video, giọng nói giả','kiểm chứng, không lan truyền'],['<b>Việc làm</b>','tự động hoá thay một số nghề','học kĩ năng mới']],note=KEY('Nguyên tắc: AI <b>hỗ trợ</b> con người; trách nhiệm cuối cùng thuộc về <b>người dùng</b>.')))
S.append(S2(c,B+' · 4','Deepfake và tin giả',card('Deepfake',ul(['Dùng AI <b>ghép mặt, giả giọng</b> tạo video giả như thật.','Nguy cơ: <b>lừa đảo, bôi nhọ, thao túng</b> dư luận.'],6)),KEY('Cách nhận biết: chuyển động môi, ánh sáng bất thường; nguồn đăng không rõ; <b>tra cứu</b> tin từ nguồn chính thống.')+WARN('Gặp cuộc gọi video “người thân” vay tiền: <b>gọi lại số thật</b> để xác minh.')))
S.append(S2(c,B+' · 4','Nguyên tắc sử dụng AI có trách nhiệm',card('Quy tắc',ul(['<b>Minh bạch</b>: nói rõ khi dùng AI.','<b>Kiểm chứng</b> trước khi tin, dùng.','<b>Bảo vệ</b> dữ liệu cá nhân.','<b>Công bằng</b>, không gây hại.','<b>Con người chịu trách nhiệm</b> cuối cùng.'],6)),KEY('Quy định pháp lí đang <b>hoàn thiện</b> (ví dụ Đạo luật AI của EU); cần theo dõi và tuân thủ.')))
S+=END(c,B,['<b>AI</b>: máy thực hiện việc cần trí tuệ con người; hiện chỉ là <b>AI hẹp</b>.','Học máy: máy <b>rút quy tắc từ dữ liệu</b>.','<b>AI tạo sinh</b> sinh nội dung mới theo prompt (LLM dự đoán từ tiếp theo).','Hạn chế: <b>ảo giác, thiên lệch</b>.','Dùng AI: minh bạch, kiểm chứng, bảo vệ dữ liệu.'],[('AI hiện có','AI hẹp'),('Bịa thông tin','ảo giác'),('Dữ liệu lệch','mô hình lệch'),('Ảnh, video giả','deepfake')],'Tin tuyệt đối vào câu trả lời của AI.',['AI ≠ học máy ≠ học sâu: <b>AI ⊃ học máy ⊃ học sâu</b>.','Phép thử Turing đánh giá máy có <b>giống người</b> khi trò chuyện.','LLM <b>không</b> tra cứu sự thật theo thời gian thực nếu không có công cụ tìm kiếm.','Dữ liệu lệch dẫn đến <b>quyết định bất công</b>.'],['<b>RAG</b>: kết hợp tìm kiếm với sinh văn bản.','<b>Kiểm toán thuật toán</b> (algorithm audit).','<b>AI có thể giải thích</b> (XAI).'],
 [('AI là gì? Nêu ba ví dụ ứng dụng.',),('Khác nhau giữa lập trình truyền thống và học máy?',),('Ảo giác của AI là gì?',),('Thiên lệch của AI xuất phát từ đâu?',),('Nêu hai nguyên tắc dùng AI có trách nhiệm.',)],
 [('Máy thực hiện việc cần trí tuệ con người; ví dụ: dịch máy, nhận diện khuôn mặt, gợi ý video.',),('Truyền thống: người viết quy tắc; học máy: máy tự rút quy tắc từ dữ liệu.',),('AI bịa thông tin nghe hợp lí nhưng sai.',),('Từ dữ liệu huấn luyện có định kiến, thiếu cân bằng.',),('Minh bạch; kiểm chứng thông tin; bảo vệ dữ liệu cá nhân.',)],
 [('Phân biệt AI hẹp và AI tổng quát; cho biết hệ thống nào hiện có.',),('Vì sao một chatbot có thể trả lời sai mà vẫn rất tự tin?',),('Đúng hay sai: (a) AI hiện nay có ý thức. (b) LLM dự đoán từ tiếp theo. (c) Dữ liệu lệch dẫn tới mô hình lệch. (d) AI luôn đúng nếu trả lời dài.',),('Một bạn dùng AI viết bài văn rồi nộp. Nhận xét.',),('Nêu hai cách nhận biết video deepfake.',),('Em được nhận cuộc gọi video “bạn” vay tiền gấp. Cần làm gì?',)],
 [('AI hẹp: giỏi một nhiệm vụ (hiện có); AI tổng quát: làm mọi việc trí tuệ (chưa có).',),('Nó sinh chuỗi từ có xác suất cao, không kiểm chứng sự thật.',),('(a) <b>Sai</b>. (b) <b>Đúng</b>. (c) <b>Đúng</b>. (d) <b>Sai</b>.',),('Vi phạm trung thực học thuật; nên dùng AI để hỗ trợ học và ghi rõ.',),('Môi, ánh sáng bất thường; nguồn đăng không rõ.',),('Không chuyển tiền; gọi lại số thật xác minh.',)],hper=2)
